"""A minimal HTML element tree for editing pages generated by Jekyll."""

from html import escape
from html.parser import HTMLParser

VOID_TAGS = frozenset({
    "area",
    "base",
    "br",
    "col",
    "embed",
    "hr",
    "img",
    "input",
    "link",
    "meta",
    "source",
    "track",
    "wbr",
})
RAW_TEXT_TAGS = frozenset({"script", "style"})


class Element:
    def __init__(self, tag, attributes=None, children=()):
        self.tag = tag
        self.attributes = dict(attributes or {})
        self.children = list(children)

    def has_class(self, name):
        return name in self.attributes.get("class", "").split()

    def matches(self, tag, class_name=None):
        return self.tag == tag and (class_name is None or self.has_class(class_name))

    def child_elements(self):
        return [child for child in self.children if isinstance(child, Element)]

    def child(self, tag):
        return next((child for child in self.child_elements() if child.tag == tag), None)

    def descendants(self):
        for child in self.child_elements():
            yield child
            yield from child.descendants()

    def find_all(self, tag, class_name=None):
        return [element for element in self.descendants() if element.matches(tag, class_name)]

    def find(self, tag, class_name=None):
        return next((element for element in self.descendants() if element.matches(tag, class_name)), None)

    def remove(self, *elements):
        self.children = [child for child in self.children if not any(child is element for element in elements)]

    def remove_descendants(self, tag, class_name=None):
        self.remove(*(child for child in self.child_elements() if child.matches(tag, class_name)))
        for child in self.child_elements():
            child.remove_descendants(tag, class_name)

    def strip_whitespace(self):
        """Removes whitespace at the start and at the end of the content."""
        self._strip_edge(0, str.lstrip)
        self._strip_edge(-1, str.rstrip)

    def _strip_edge(self, index, strip):
        while self.children and isinstance(self.children[index], str):
            stripped = strip(self.children[index])
            if stripped:
                self.children[index] = stripped
                return
            del self.children[index]

    def text(self):
        return "".join(child if isinstance(child, str) else child.text() for child in self.children)

    def to_html(self):
        attributes = "".join(_attribute_html(name, value) for name, value in self.attributes.items())
        if self.tag in VOID_TAGS:
            return f"<{self.tag}{attributes}>"
        return f"<{self.tag}{attributes}>{self.inner_html()}</{self.tag}>"

    def inner_html(self):
        return "".join(self._child_html(child) for child in self.children)

    def _child_html(self, child):
        if isinstance(child, Element):
            return child.to_html()
        return child if self.tag in RAW_TEXT_TAGS else escape(child, quote=False)


def _attribute_html(name, value):
    return f" {name}" if value is None else f' {name}="{escape(value)}"'


def parse(html):
    builder = _TreeBuilder()
    builder.feed(html)
    builder.close()
    return builder.document


class _TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.document = Element("#document")
        self.open_elements = [self.document]

    def handle_starttag(self, tag, attrs):
        element = Element(tag, attrs)
        self.open_elements[-1].children.append(element)
        if tag not in VOID_TAGS:
            self.open_elements.append(element)

    def handle_endtag(self, tag):
        if any(element.tag == tag for element in self.open_elements[1:]):
            while self.open_elements.pop().tag != tag:
                pass

    def handle_data(self, data):
        self.open_elements[-1].children.append(data)
